const { resolveBoundCommand } = require('./control-bound-protocol')
const crypto = require('node:crypto')

function createMomentaryControls ({ routes, send, onError = () => {}, leaseMs = 3000,
  now = Date.now, setTimer = setTimeout, clearTimer = clearTimeout }) {
  const records = new Map()
  const epoch = crypto.randomBytes(16).toString('hex')
  let timer = null
  let closed = false
  const destination = command => JSON.stringify([command.device, command.path])
  const occupied = key => [...records.values()].some(record => record.active && record.target === key)

  function release (record) {
    if (!record.active) return
    record.active = false
    if (!occupied(record.target)) {
      try { send(record.off, record.identity) } catch (error) { onError(error) }
    }
  }
  function sweep () {
    const time = now()
    for (const [key, record] of records) {
      if (record.active && record.until <= time) release(record)
      if (record.identity.expiry <= time) { release(record); records.delete(key) }
    }
  }
  function schedule () {
    if (timer) clearTimer(timer)
    timer = null
    const deadlines = [...records.values()].filter(record => record.active).map(record => record.until)
    if (closed || !deadlines.length) return
    timer = setTimer(() => { timer = null; sweep(); schedule() }, Math.max(1, Math.min(...deadlines) - now()))
    timer.unref?.()
  }
  function handle (message, identity) {
    if (closed) throw Error('Momentary controls unavailable')
    const request = message?._controlPanel
    const hold = request?.hold
    const route = routes.get(request?.id)
    if (route?.control.buttonBehavior !== 'momentary' || route.control.mode !== 'both') {
      throw Error('This control is not a momentary button')
    }
    if (!hold || hold.epoch !== epoch || !/^[A-Za-z0-9_-]{1,64}$/.test(hold.client || '') ||
      !Number.isSafeInteger(hold.seq) || hold.seq < 1 ||
      !['start', 'renew', 'release'].includes(hold.action) ||
      request.value !== (hold.action !== 'release') ||
      typeof identity?.token !== 'string' || !Number.isFinite(identity.expiry) || identity.expiry <= now()) {
      throw Error('Invalid momentary command')
    }
    const command = resolveBoundCommand(routes, message)
    sweep()
    const key = JSON.stringify([identity.token, request.id, hold.client])
    let record = records.get(key)
    if (!record) {
      if (records.size >= 1024) throw Error('Momentary client limit reached')
      record = { seq: 0, active: false, controlId: request.id, target: destination(command), identity,
        off: resolveBoundCommand(routes, { _controlPanel: { kind: 'command', id: request.id, value: false, final: true } }) }
      records.set(key, record)
    }
    // Keep the sequence watermark after release: a delayed press must not re-enable the device.
    if (hold.seq <= record.seq) return { held: record.active }
    record.seq = hold.seq
    if (hold.action === 'release') release(record)
    else if (hold.action === 'start') {
      if ([...records.values()].some(other => other.active && other.target === record.target &&
        !Object.is(other.off.payload, record.off.payload))) throw Error('Conflicting momentary state mapping')
      const alreadyHeld = occupied(record.target)
      if (!alreadyHeld) send(command, identity)
      record.active = true
      record.until = Math.min(now() + leaseMs, identity.expiry)
    } else if (record.active) record.until = Math.min(now() + leaseMs, identity.expiry)
    schedule()
    return { held: record.active }
  }
  return {
    epoch,
    handle,
    isHeld (command) { sweep(); return occupied(destination(command)) },
    releaseControl (id) {
      for (const record of records.values()) if (record.controlId === id) release(record)
      schedule()
    },
    releaseSession (token) {
      for (const [key, record] of records) {
        if (record.identity.token === token) { release(record); records.delete(key) }
      }
      schedule()
    },
    close () {
      closed = true
      if (timer) clearTimer(timer)
      timer = null
      for (const record of records.values()) release(record)
      records.clear()
    }
  }
}

module.exports = { createMomentaryControls }
